namespace PlatformHub.Domain.Entities;
public abstract class ScopedBusinessEntity { public long Id { get; set; } public long TenantId { get; set; } public long? BranchId { get; set; } public long? ProjectId { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedUtc { get; set; } = DateTime.UtcNow; }
public sealed class ProductCategory : ScopedBusinessEntity { public string Code { get; set; } = ""; public string Name { get; set; } = ""; }
public sealed class ProductBrand : ScopedBusinessEntity { public string Code { get; set; } = ""; public string Name { get; set; } = ""; }
public sealed class ProductUnit : ScopedBusinessEntity { public string Code { get; set; } = ""; public string Name { get; set; } = ""; public decimal ConversionFactor { get; set; } = 1m; }
public sealed class ProductModel : ScopedBusinessEntity { public string Code { get; set; } = ""; public string Name { get; set; } = ""; public long? BrandId { get; set; } }
public sealed class ProductBarcode : ScopedBusinessEntity { public long ProductId { get; set; } public string Barcode { get; set; } = ""; public bool IsPrimary { get; set; } }
public sealed class InventoryStore : ScopedBusinessEntity { public string Code { get; set; } = ""; public string Name { get; set; } = ""; public string? Address { get; set; } }
public sealed class StockMovement : ScopedBusinessEntity { public long ProductId { get; set; } public long StoreId { get; set; } public string MovementType { get; set; } = ""; public decimal QuantityIn { get; set; } public decimal QuantityOut { get; set; } public decimal UnitCost { get; set; } public string ReferenceType { get; set; } = ""; public long? ReferenceId { get; set; } public DateTime TransactionUtc { get; set; } = DateTime.UtcNow; public string? Notes { get; set; } }
public sealed class StockSnapshot : ScopedBusinessEntity { public long ProductId { get; set; } public long StoreId { get; set; } public DateOnly SnapshotDate { get; set; } public decimal Quantity { get; set; } public decimal AverageUnitCost { get; set; } }
public sealed class StockTransfer : ScopedBusinessEntity { public string TransferNo { get; set; } = ""; public long FromStoreId { get; set; } public long ToStoreId { get; set; } public long ProductId { get; set; } public decimal Quantity { get; set; } public string Status { get; set; } = "Draft"; public DateTime TransferDateUtc { get; set; } = DateTime.UtcNow; }
public sealed class AccountHead : ScopedBusinessEntity { public string Code { get; set; } = ""; public string Name { get; set; } = ""; public string AccountType { get; set; } = ""; public long? ParentAccountId { get; set; } public bool IsControlAccount { get; set; } }
public sealed class AccountingVoucher : ScopedBusinessEntity { public string VoucherNo { get; set; } = ""; public string VoucherType { get; set; } = ""; public DateOnly VoucherDate { get; set; } public string Status { get; set; } = "Draft"; public string? Narration { get; set; } public decimal TotalDebit { get; set; } public decimal TotalCredit { get; set; } public DateTime? PostedUtc { get; set; } }
public sealed class AccountingVoucherLine { public long Id { get; set; } public long VoucherId { get; set; } public long AccountHeadId { get; set; } public decimal Debit { get; set; } public decimal Credit { get; set; } public string? Description { get; set; } public long? CostCenterId { get; set; } }
public sealed class BusinessDocument : ScopedBusinessEntity { public string DocumentType { get; set; } = ""; public string DocumentNo { get; set; } = ""; public DateOnly DocumentDate { get; set; } public long? PartyAccountId { get; set; } public string PartyName { get; set; } = ""; public string Status { get; set; } = "Draft"; public decimal Subtotal { get; set; } public decimal Discount { get; set; } public decimal TaxAmount { get; set; } public decimal TotalAmount { get; set; } public string? Notes { get; set; } }
public sealed class BusinessDocumentLine { public long Id { get; set; } public long DocumentId { get; set; } public long ProductId { get; set; } public long? StoreId { get; set; } public decimal Quantity { get; set; } public decimal UnitPrice { get; set; } public decimal Discount { get; set; } public decimal TaxAmount { get; set; } public decimal LineTotal { get; set; } }
